craftdr=[x for x in craft.findall('./recipes/recipe') if (x.get('id') or '').lower().startswith('drink') and x.get('policy')=='gated']; ck('12 gated drink progression rows',len(craftdr)==12); ck('all gated drink progression rows primary Drink Preparation',all(x.get('primary_skill')=='skill.drink_preparation' for x in craftdr)); boiled=craft.find("./recipes/recipe[@id='drinkJarBoiledWater']"); ck('boiled water remains universal',boiled is not None and boiled.get('policy')=='universal'); rkdr=[x for x in rk.findall('recipe') if (x.get('name') or '').lower().startswith('drink')]; ck('drink recipe Knowledge categorized Drink Preparation',all(x.get('category')=='drink_preparation' for x in rkdr))
