# Buff identity values
ck('Beer physical resistance +15','buffRebirthPreparedBeerPainResistance' in buffs and 'PhysicalDamageResist" operation="base_add" value="15"' in buffs); ck('Red Tea mobility restored','buffRebirthPreparedRedTeaMobility' in buffs and 'CarryCapacity" operation="base_add" value="15"' in buffs and buffs.count('operation="perc_add" value="0.5"')>=2); ck('Goldenrod mining identity restored','buffRebirthPreparedGoldenrodMining' in buffs and 'tags="stone"' in buffs and 'tags="metal"' in buffs and 'tags="miningTool"' in buffs); ck('Yucca field-work identity restored without duplicate cooling','buffRebirthPreparedYuccaWork' in buffs and 'tags="earth,wood"' in buffs and 'HyperthermalResist' not in buffs[buffs.find('buffRebirthPreparedYuccaWork'):]); ck('Coffee duplicate buff not added','buffRebirthPreparedCoffee' not in buffs and '"drinkJarCoffee",new RebirthPreparedDrinkProfile' not in svc)
