ck('Chunk K debug command','chunkkbonus' in dbg and 'ExecuteChunkKBonus' in dbg); ck('Chunk K vectors exposed','RebirthDrinkPreparationSignatureService.RunVectors()' in dbg); ck('service Rebirth-only gates',svc.count('RebirthSurvivorMode.IsEnabledForCurrentWorld()')>=4); ck('activation server-only','consumer.world.IsRemote()' in svc); ck('PC013 compatibility allows later normal Skills',"45+ skills (later approved normal Skills allowed)" in txt('BuildScripts/Progression/validate_advanced_disciplines_pc013.py'))
