for rel in ['Scripts/Survivor/Backgrounds/RebirthDrinkPreparationSignatureService.cs','Scripts/Survivor/Backgrounds/RebirthDrinkPreparationSignatureNetPackages.cs','Scripts/Metabolism/RebirthMetabolismModels.cs','Scripts/Metabolism/RebirthMetabolismStateRepository.cs','Scripts/Metabolism/RebirthMetabolismService.cs','Scripts/Survivor/Progression/RebirthServiceCraftSkillService.cs','Scripts/Survivor/Progression/RebirthSurvivorProgressionInstaller.cs','Scripts/Survivor/Debug/ConsoleCmdRebirthSurvivor.cs']:
 ck('delimiter '+Path(rel).name,balanced(rel))
